+function OutlineSidebar() {
+  if (!outlineOpen.value) return null;
+  const entries = outlineEntries.value;
+  return (
+    <nav class="gramaire__outline" aria-label="Document outline">
+      {entries.length === 0 ? (
+        <div class="gramaire__outline-empty">Nothing to outline yet.</div>
+      ) : (
+        <ul class="gramaire__outline-list">
